CREATE TABLE "workspace_code_reading_sessions" ("id" uuid PRIMARY KEY DEFAULT gen_random_uuid(),"workspace_id" uuid NOT NULL REFERENCES "workspaces"("id") ON DELETE CASCADE,"project_id" integer NOT NULL REFERENCES "workspace_project_profiles"("id") ON DELETE CASCADE,"question" text NOT NULL,"output_mode" varchar(24) NOT NULL,"status" varchar(20) NOT NULL DEFAULT 'queued',"model" varchar(200),"tool_calls_used" integer NOT NULL DEFAULT 0,"bytes_read" integer NOT NULL DEFAULT 0,"max_tool_calls" integer NOT NULL DEFAULT 8,"max_bytes_read" integer NOT NULL DEFAULT 163840,"final_json" text,"error_message" text,"created_at" timestamptz NOT NULL DEFAULT now(),"updated_at" timestamptz NOT NULL DEFAULT now(),"finished_at" timestamptz);
CREATE INDEX "workspace_code_reading_sessions_project_created_idx" ON "workspace_code_reading_sessions" ("workspace_id","project_id","created_at");
CREATE TABLE "workspace_code_reading_steps" ("id" serial PRIMARY KEY,"session_id" uuid NOT NULL REFERENCES "workspace_code_reading_sessions"("id") ON DELETE CASCADE,"sequence" integer NOT NULL,"kind" varchar(16) NOT NULL,"tool_name" varchar(40),"status" varchar(16) NOT NULL,"error_message" text,"created_at" timestamptz NOT NULL DEFAULT now());
CREATE INDEX "workspace_code_reading_steps_session_idx" ON "workspace_code_reading_steps" ("session_id","sequence");
CREATE TABLE "workspace_code_reading_evidence" ("id" serial PRIMARY KEY,"session_id" uuid NOT NULL REFERENCES "workspace_code_reading_sessions"("id") ON DELETE CASCADE,"evidence_ref" varchar(20) NOT NULL,"relative_path" text NOT NULL,"start_line" integer NOT NULL,"end_line" integer NOT NULL,"excerpt" text NOT NULL);
CREATE UNIQUE INDEX "workspace_code_reading_evidence_ref_unique" ON "workspace_code_reading_evidence" ("session_id","evidence_ref");
CREATE INDEX "workspace_code_reading_evidence_session_idx" ON "workspace_code_reading_evidence" ("session_id","id");
